package com.witchersbestiary.fist;
import java.util.UUID;
import net.minecraft.network.*;import net.minecraft.network.codec.PacketCodec;import net.minecraft.network.packet.CustomPayload;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.Identifier;
public final class DuelPackets {
 public record Control(UUID session,int action) implements CustomPayload {public static final Id<Control>ID=new Id<>(Identifier.of("witchersbestiary:duel_control"));public static final PacketCodec<RegistryByteBuf,Control> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeVarInt(p.action);},b->new Control(b.readUuid(),b.readVarInt()));public Id<Control>getId(){return ID;}}
 public record Input(UUID session,int action) implements CustomPayload {public static final Id<Input>ID=new Id<>(Identifier.of("witchersbestiary:duel_input"));public static final PacketCodec<RegistryByteBuf,Input> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeVarInt(p.action);},b->new Input(b.readUuid(),b.readVarInt()));public Id<Input>getId(){return ID;}}
 public record View(UUID session,boolean present,String stage,String opponent,boolean acceptedSelf,boolean acceptedOther,int seconds,String result,String winner) implements CustomPayload {public static final Id<View>ID=new Id<>(Identifier.of("witchersbestiary:duel_view"));public static final PacketCodec<RegistryByteBuf,View> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeBoolean(p.present);b.writeString(p.stage);b.writeString(p.opponent);b.writeBoolean(p.acceptedSelf);b.writeBoolean(p.acceptedOther);b.writeVarInt(p.seconds);b.writeString(p.result);b.writeString(p.winner);},b->new View(b.readUuid(),b.readBoolean(),b.readString(32),b.readString(64),b.readBoolean(),b.readBoolean(),b.readVarInt(),b.readString(32),b.readString(64)));public Id<View>getId(){return ID;}}
 public static void send(ServerPlayerEntity p,DuelSessions.Session d){boolean side=d.a.equals(p.getUuid());var other=p.getServer().getPlayerManager().getPlayer(side?d.b:d.a);var winner=d.winner==null?null:p.getServer().getPlayerManager().getPlayer(d.winner);var view=new View(d.id,true,d.stage.name(),other==null?"":other.getName().getString(),side?d.acceptedA:d.acceptedB,side?d.acceptedB:d.acceptedA,(int)Math.max(0,(d.deadline-p.getServer().getTicks()+19)/20),d.result.name(),winner==null?"":winner.getName().getString());if(net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.canSend(p,View.ID))net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.send(p,view);
  if(d.stage==DuelSessions.Stage.COUNTDOWN||d.stage==DuelSessions.Stage.ACTIVE||d.stage==DuelSessions.Stage.FINISHED&&d.started>=0){var own=side?d.fight.player:d.fight.opponent;var target=side?d.fight.opponent:d.fight.player;var state=new FistPackets.State(true,other==null?0:other.getId(),d.stage==DuelSessions.Stage.COUNTDOWN?Math.max(1,3-d.fight.ticks/20):0,(float)target.health,(float)own.stamina,(float)own.maxStamina,(float)own.health,view.opponent(),target.action.name());FistPackets.sendState(p,state,new FistPackets.Pose(p.getId(),true,own.action.name(),own.actionTicks));}
 }
 public static void clear(ServerPlayerEntity p){if(net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.canSend(p,View.ID))net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.send(p,new View(new UUID(0,0),false,"","",false,false,0,"",""));FistPackets.send(p,null);}
 public static void initialize(){var c=net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry.playC2S();c.register(Control.ID,Control.CODEC);c.register(Input.ID,Input.CODEC);net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry.playS2C().register(View.ID,View.CODEC);net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.registerGlobalReceiver(Control.ID,(packet,ctx)->ctx.server().execute(()->DuelSessions.control(ctx.player(),packet.session,packet.action)));net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking.registerGlobalReceiver(Input.ID,(packet,ctx)->ctx.server().execute(()->{if(packet.action>=0&&packet.action<=FistFightSession.Action.DODGE.ordinal())DuelSessions.input(ctx.player(),packet.session,FistFightSession.Action.values()[packet.action]);}));}
}
